import { setTimeout as sleep } from 'node:timers/promises';
import { JOB_COLUMNS, nowIso, openDatabase, transaction, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
/** Total attempts per job, including the first. */
const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. Must be between 250 and 2000 ms. */
const RETRY_DELAY_MS = 500;

const db = openDatabase();
let stopping = false;

const selectDue = db.prepare(
  `SELECT id FROM jobs WHERE status = 'queued' AND (next_run_at IS NULL OR next_run_at <= ?) ORDER BY seq ASC LIMIT 1`,
);
const claim = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, next_run_at = NULL, updated_at = ?
   WHERE id = ? AND status = 'queued'`,
);
const selectById = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`);
const setProgress = db.prepare(
  `UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const complete = db.prepare(
  `UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const requeueWithDelay = db.prepare(
  `UPDATE jobs SET status = 'queued', progress_completed = 0, error = NULL, next_run_at = ?, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const failPermanently = db.prepare(
  `UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = 'transient failure', updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
/** Returns an interrupted attempt to the queue without counting it, so it is processed again as the same attempt. */
const requeueInterrupted = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const recoverRunning = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, updated_at = ?
   WHERE status = 'running'`,
);
const writeHeartbeat = db.prepare(
  `INSERT INTO heartbeat (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`,
);
const clearHeartbeat = db.prepare(`DELETE FROM heartbeat WHERE name = 'worker'`);

function beat(): void {
  try {
    writeHeartbeat.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

/** Claims the oldest queued job that is due, marking it running and counting the new attempt. */
function claimNext(): JobRow | undefined {
  return transaction(db, () => {
    const due = selectDue.get(Date.now()) as unknown as { id: string } | undefined;
    if (!due) return undefined;
    claim.run(nowIso(), due.id);
    return selectById.get(due.id) as unknown as JobRow;
  });
}

async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  // Simulated transient failure: fails at the first step, before any progress.
  if (attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) {
      requeueInterrupted.run(nowIso(), job.id);
      return;
    }
    transaction(db, () => {
      if (attempt < MAX_ATTEMPTS) requeueWithDelay.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
      else failPermanently.run(nowIso(), job.id);
    });
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      requeueInterrupted.run(nowIso(), job.id);
      return;
    }
    setProgress.run(step, nowIso(), job.id);
  }
  complete.run(job.input.toUpperCase(), nowIso(), job.id);
}

function onSignal(): void {
  stopping = true;
}

process.on('SIGINT', onSignal);
process.on('SIGTERM', onSignal);

// Anything left "running" belonged to a worker that died. Process it again.
transaction(db, () => recoverRunning.run(nowIso()));
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNext();
    if (job) await runAttempt(job);
    else await sleep(POLL_MS);
  } catch (err) {
    console.error('worker loop error:', err);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeatTimer);
try {
  clearHeartbeat.run();
} catch {
  // best effort; the heartbeat goes stale within 3 s anyway
}
db.close();
console.log('worker stopped');

