1	import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
2	import { randomUUID } from 'node:crypto';
3	import { readFileSync } from 'node:fs';
4	import { JOB_COLUMNS, nowIso, openDatabase, toJob, transaction, type Job, type JobRow } from './db.ts';
5	import { validateSubmission, type FieldError, type Submission } from './validate.ts';
6	
7	/** A worker heartbeat older than this means the worker is down. */
8	const WORKER_FRESH_MS = 3_000;
9	const MAX_BODY_BYTES = 16 * 1024;
10	const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
11	const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;
12	
13	const db = openDatabase();
14	const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
15	
16	const selectById = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`);
17	const selectByKey = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE idempotency_key = ?`);
18	const selectAll = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`);
19	const insertJob = db.prepare(
20	  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, created_at, updated_at)
21	   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?)`,
22	);
23	const selectWorkerHeartbeat = db.prepare(`SELECT at FROM heartbeat WHERE name = 'worker'`);
24	
25	function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
26	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
27	  res.end(JSON.stringify(body));
28	}
29	
30	function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
31	  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
32	}
33	
34	function readBody(req: IncomingMessage): Promise<string | undefined> {
35	  return new Promise((resolve, reject) => {
36	    const chunks: Buffer[] = [];
37	    let size = 0;
38	    let tooLarge = false;
39	    req.on('data', (chunk: Buffer) => {
40	      size += chunk.length;
41	      if (size > MAX_BODY_BYTES) tooLarge = true;
42	      else chunks.push(chunk);
43	    });
44	    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
45	    req.on('error', reject);
46	  });
47	}
48	
49	type SubmitOutcome = { status: 200 | 201; job: Job } | { status: 409 };
50	
51	function submit(submission: Submission, key: string | null): SubmitOutcome {
52	  return transaction(db, () => {
53	    if (key !== null) {
54	      const existing = selectByKey.get(key) as unknown as JobRow | undefined;
55	      if (existing) {
56	        const same =
57	          existing.input === submission.input &&
58	          existing.steps === submission.steps &&
59	          existing.fail_attempts === submission.failAttempts;
60	        return same ? { status: 200, job: toJob(existing) } : { status: 409 };
61	      }
62	    }
63	    const id = randomUUID();
64	    const now = nowIso();
65	    insertJob.run(id, submission.input, submission.steps, submission.failAttempts, key, now, now);
66	    return { status: 201, job: toJob(selectById.get(id) as unknown as JobRow) };
67	  });
68	}
69	
70	async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
71	  const fields: FieldError[] = [];
72	
73	  const rawKey = req.headers['idempotency-key'];
74	  let key: string | null = null;
75	  if (rawKey !== undefined) {
76	    if (typeof rawKey === 'string' && IDEMPOTENCY_KEY.test(rawKey)) key = rawKey;
77	    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
78	  }
79	
80	  const raw = await readBody(req);
81	  const rawType = req.headers['content-type'];
82	  const contentType = (typeof rawType === 'string' ? rawType : '').split(';')[0]!.trim().toLowerCase();
83	  let submission: Submission | undefined;
84	  if (raw === undefined) {
85	    fields.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
86	  } else if (contentType !== 'application/json') {
87	    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
88	  } else {
89	    let parsed: unknown;
90	    let parseOk = true;
91	    try {
92	      parsed = JSON.parse(raw);
93	    } catch {
94	      parseOk = false;
95	      fields.push({ field: 'body', message: 'is not valid JSON' });
96	    }
97	    if (parseOk) {
98	      const result = validateSubmission(parsed);
99	      if (result.ok) submission = result.value;
100	      else fields.push(...result.fields);
101	    }
102	  }
103	
104	  if (fields.length > 0 || submission === undefined) {
105	    return sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
106	  }
107	
108	  const outcome = submit(submission, key);
109	  if (outcome.status === 409) {
110	    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
111	  }
112	  send(res, outcome.status, outcome.job);
113	}
114	
115	function workerIsUp(): boolean {
116	  const row = selectWorkerHeartbeat.get() as unknown as { at: number } | undefined;
117	  return row !== undefined && Date.now() - Number(row.at) <= WORKER_FRESH_MS;
118	}
119	
120	function route(req: IncomingMessage, res: ServerResponse): void | Promise<void> {
121	  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
122	  const method = req.method ?? 'GET';
123	
124	  const methodNotAllowed = (allow: string): void => {
125	    res.setHeader('allow', allow);
126	    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);
127	  };
128	
129	  if (pathname === '/health') {
130	    if (method !== 'GET') return methodNotAllowed('GET');
131	    return send(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
132	  }
133	  if (pathname === '/') {
134	    if (method !== 'GET') return methodNotAllowed('GET');
135	    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
136	    res.end(uiHtml);
137	    return;
138	  }
139	  if (pathname === '/api/jobs') {
140	    if (method === 'GET') {
141	      const jobs = (selectAll.all() as unknown as JobRow[]).map(toJob);
142	      return send(res, 200, { jobs });
143	    }
144	    if (method === 'POST') return handleCreate(req, res);
