  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  const methodNotAllowed = (allow: string): void => {
    res.setHeader('allow', allow);
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);
  };

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed('GET');
    return send(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed('GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const jobs = (selectAll.all() as unknown as JobRow[]).map(toJob);
      return send(res, 200, { jobs });
    }
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed('GET, POST');
  }
  const match = JOB_PATH.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed('GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const row = selectById.get(id) as unknown as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'No such job.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  Promise.resolve()
    .then(() => route(req, res))
    .catch((err: unknown) => {
      console.error('request failed:', err);
      if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal error.');
    });
});

server.on('error', (err) => {
  console.error(`server failed to listen on ${port}: ${err.message}`);
  process.exit(1);
});

server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
process.on('SIGTERM', () => {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 1_000).unref();
});

